   col=g[r][c];st=[(r,c)];seen.add((r,c));p=[]
   while st:
    x=st.pop();p.append(x)
    for q in [(x[0]+1,x[1]),(x[0]-1,x[1]),(x[0],x[1]+1),(x[0],x[1]-1)]:
     if 0<=q[0]<9 and 0<=q[1]<6 and q not in seen and g[q[0]][q[1]]==col:seen.add(q);st.append(q)
   comps.append((col,set(p)))
positions=[p for col,p in comps]; occ={(9,c) for c in range(6)}
for t in range(20):
 movable=[]
 for i,p in enumerate(positions):
  if all((r+1,c) not in occ or (r+1,c) in p for r,c in p):movable.append(i)
 if not movable: break
 for i in movable: positions[i]={(r+1,c) for r,c in positions[i]}
 occ={(9,c) for c in range(6)}
